/* Trusted reference Express API. Not generated by Qwen0.5B. */
const express = require('express');
const {spawnSync} = require('node:child_process');
const path = require('node:path');
const app = express();
app.disable('x-powered-by');
app.use(express.json({limit:'64kb'}));

const backend = path.resolve(__dirname, '..', 'backend', 'storage.py');
function call(action, payload={}) {
  const result = spawnSync('python3', ['-I', '-B', backend], {
    input:JSON.stringify({action,payload}), encoding:'utf8',
    timeout:6000, maxBuffer:512*1024,
    env:{...process.env, PYTHONDONTWRITEBYTECODE:'1'}
  });
  if (result.error || result.status !== 0) throw Error('Python bridge unavailable');
  let parsed;
  try {parsed = JSON.parse(result.stdout);} catch {throw Error('Invalid Python response');}
  if (!parsed.ok) {
    const error = Error(parsed.error);
    error.status = parsed.kind === 'not_found' ? 404 : 400;
    throw error;
  }
  return parsed.data;
}

const handler = (action, args=()=>({})) => (req,res,next) => {
  try {res.json({data:call(action,args(req))});} catch (error) {next(error);}
};
app.get('/api/health', (_req,res) => res.json({ok:true,service:'project-manager'}));
app.get('/api/overview', handler('overview'));
app.post('/api/projects', handler('create_project',req=>req.body));
app.patch('/api/projects/:id', handler('update_project',req=>({...req.body,id:req.params.id})));
app.delete('/api/projects/:id',handler('delete_project',req=>({id:req.params.id})));
app.post('/api/tasks',handler('create_task',req=>req.body));
app.patch('/api/tasks/:id',handler('update_task',req=>({...req.body,id:req.params.id})));
app.delete('/api/tasks/:id',handler('delete_task',req=>({id:req.params.id})));

const staticDir=path.resolve(__dirname,'..','client','dist');
app.use(express.static(staticDir));
app.get('/{*splat}',(req,res,next)=>{
  if (req.path.startsWith('/api/')) return next();
  res.sendFile(path.join(staticDir,'index.html'));
});
app.use((err,_req,res,_next)=>{
  const status=err.status || (err.type==='entity.too.large' ? 413 : 500);
  res.status(status).json({error:status===500?'Internal server error':err.message});
});
if (require.main === module) {
  app.listen(Number(process.env.PORT||3000),'0.0.0.0',()=>
    console.log('Project manager ready on port '+(process.env.PORT||3000)));
}
module.exports=app;
